func mcpToolResultText(method string, data json.RawMessage) *mcplib.CallToolResult {
	return mcplib.NewToolResultText(bound.EndpointResponse(method, data))
}

// mcpToolError keeps provider-controlled typed endpoint errors within the MCP
// text-result budget just like successful endpoint results.
func mcpToolError(message string) *mcplib.CallToolResult {
	return mcplib.NewToolResultError(bound.Text(message))
}

func mcpToolPageResultText(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor string) *mcplib.CallToolResult {
	return mcplib.NewToolResultText(bound.EndpointPageResponse(method, data, bound.PageOptions{
		Cursor:         cursor,
		CursorParam:    pageConfig.CursorParam,
		NextCursorPath: pageConfig.NextCursorPath,
	}))
}

func newMCPClient() (*client.Client, error) {
	cfg, err := newMCPConfig()
	if err != nil {
		return nil, err
	}
	return newMCPClientFromConfig(cfg), nil
}

func newMCPConfig() (*config.Config, error) {
	cfg, err := config.Load("")
	if err != nil {
		return nil, fmt.Errorf("loading config: %w", err)
	}
	return cfg, nil
}

func newMCPClientFromConfig(cfg *config.Config) *client.Client {
	c := client.New(cfg, 60*time.Second, defaultMCPRateLimit)
	// Agents calling through MCP need fresh data every call. The on-disk
	// response cache survives across MCP server invocations, so a
	// DELETE/PATCH followed by a GET would otherwise return the
	// pre-mutation snapshot for up to the cache TTL. The interactive CLI
	// constructs its own client and is unaffected.
	c.NoCache = true
	return c
}

func mcpDBPath() (string, error) {
	dir, err := cliutil.DataDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "data.db"), nil
}

// toolResultJSON renders v as the indented JSON body of an MCP text result,
// surfacing a marshal failure as a tool error instead of empty content.
func toolResultJSON(v any) (*mcplib.CallToolResult, error) {
	text, err := bound.JSON(v)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}

func handleContext(_ context.Context, _ mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	paths := map[string]string{}
	if dir, err := cliutil.ConfigDir(); err == nil {
		paths["config_dir"] = dir
	}
	if dir, err := cliutil.DataDir(); err == nil {
		paths["data_dir"] = dir
	}
	if dir, err := cliutil.StateDir(); err == nil {
		paths["state_dir"] = dir
	}
	if dir, err := cliutil.CacheDir(); err == nil {
		paths["cache_dir"] = dir
	}
	ctx := map[string]any{
		"api":         "screencloud",
		"description": "A Playgrounds release and fleet-operations CLI that understands both Studio and the app content service.",
		"archetype":   "generic",
		"tool_count":  1,
		"paths":       paths,
		// tool_surface tells agents which surface a capability lives on.
		"tool_surface": "MCP exposes typed endpoint tools plus a runtime mirror of user-facing CLI commands. Endpoint tools keep typed schemas; command-mirror tools shell out to the companion screencloud-pp-cli binary.",
		// learn_protocol is generated from the single shared source of
		// truth (the exported constant internal/learn.RecallFirstProtocol)
		// also consumed by the CLI agent-context command, so the MCP and
		// CLI agent surfaces cannot drift.
		"learn_protocol": learn.RecallFirstProtocol,
		"auth": map[string]any{
			"type": "bearer_token",
			"env_vars": []map[string]any{
				{
					"name":        "SCREENCLOUD_API_KEY",
					"kind":        "per_call",
					"required":    true,
					"sensitive":   true,
					"description": "Set to your API credential.",
				},
			},
			"docs_url": "https://graphql.us.screencloud.com",
		},
		"resources": []map[string]any{
			{
				"name":        "graphql",
				"description": "Execute maintained or user-supplied Studio GraphQL documents",
				"endpoints":   []string{"request"},
				"searchable":  true,
				"writable":    true,
			},
		},
		"query_tips": []string{
			"Pagination uses cursor-based paging. Pass after parameter for subsequent pages.",
			"Control page size with the limit parameter (default 100).",
		},
		// Command-mirror capabilities are exposed through MCP by shelling out
		// to the companion CLI binary.
		"command_mirror_capabilities": []map[string]string{
			{"name": "Release impact map", "command": "playgrounds impact", "description": "Map the synchronized spaces, channels, playlists, and screens related to a reviewed Playgrounds working copy before publishing.", "rationale": "It combines a deterministic working-copy fingerprint with sanitized direct-cast, association, share, channel, playlist, and screen identifiers while marking incomplete mirrors.", "via": "mcp-command-mirror"},
			{"name": "Fleet readiness audit", "command": "playgrounds readiness", "description": "Find missing, inactive, outdated, dangling, and inconsistent Playgrounds deployments across the organization.", "rationale": "It joins spaces, installations, instances, versions, and sanitized Playgrounds metadata in the local store.", "via": "mcp-command-mirror"},
			{"name": "Privacy-preserving config drift", "command": "playgrounds config-drift", "description": "Detect structurally divergent Playgrounds configurations without storing or revealing private values.", "rationale": "It fingerprints sanitized configuration-key sets and groups matching synchronized instance IDs without retaining private values.", "via": "mcp-command-mirror"},
			{"name": "Interrupted-create reconciler", "command": "playgrounds create-reconcile", "description": "Turn a partial create receipt into a resume or cleanup plan; a no-op conclusion requires live verification.", "rationale": "It reconciles a redacted local receipt against both Studio instance state and Playgrounds content state.", "via": "mcp-command-mirror"},
			{"name": "Playgrounds contract check", "command": "playgrounds contract-check", "description": "Verify the current management and viewer content contracts after minting ephemeral scoped JWTs, without changing Playgrounds content.", "rationale": "It coordinates ScreenCloud's two scoped JWT types with file, data, and viewer-package assertions across separate services.", "via": "mcp-command-mirror"},
			{"name": "Preview drift queue", "command": "playgrounds preview-drift", "description": "Find unpublished previews, production-ahead conflicts, and preview work that has waited too long.", "rationale": "It compares the Playgrounds-specific preview workspace convention and last-modified metadata across mapped app instances.", "via": "mcp-command-mirror"},
			{"name": "Least-privilege capability matrix", "command": "auth capabilities", "description": "Explain whether the current identity appears able to run a supported mapped command without exposing token material or raw effective grants.", "rationale": "It compares currentToken and currentUser structure with the published 25-domain permission catalog and reports available, missing, or unknown states before execution.", "via": "mcp-command-mirror"},
		},
		"playbook": []map[string]string{
			{"topic": "Release impact map", "insight": "It combines a Playgrounds working-copy diff with direct casts, associations, shares, channels, playlists, and screens that no single endpoint returns, while marking stale or permission-incomplete results."},
			{"topic": "Fleet readiness audit", "insight": "It joins spaces, installations, instances, apps, versions, and sanitized metadata in the local store."},
			{"topic": "Privacy-preserving config drift", "insight": "It fingerprints sanitized configuration-key sets across synced instances and resolves the affected spaces locally."},
			{"topic": "Interrupted-create reconciler", "insight": "It reconciles a redacted local receipt against both Studio instance state and Playgrounds content state."},
			{"topic": "Playgrounds contract check", "insight": "It coordinates ScreenCloud's two scoped JWT types with file, data, and viewer-package assertions across separate services."},
			{"topic": "Preview drift queue", "insight": "It compares the Playgrounds-specific preview workspace convention and last-modified metadata across mapped app instances."},
			{"topic": "Least-privilege capability matrix", "insight": "It compares currentToken and currentUser structure with the published 25-domain permission catalog and reports available, missing, or unknown states before execution."},
		},
	}
	return toolResultJSON(ctx)
}

